alter table public.timeline_daw_normalization_support_cases add column if not exists escalation_level integer not null default 0 check(escalation_level between 0 and 3),add column if not exists last_notified_at timestamptz;create table if not exists public.timeline_daw_normalization_support_notifications(id text primary key,idempotency_key text not null unique,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,case_id text not null references public.timeline_daw_normalization_support_cases(id) on delete cascade,level integer not null check(level between 1 and 3),title text not null,acknowledged_at timestamptz,created_at timestamptz not null default now());alter table public.timeline_daw_normalization_support_notifications enable row level security;create policy timeline_daw_normalization_support_notifications_owner on public.timeline_daw_normalization_support_notifications for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());create table if not exists public.timeline_daw_normalization_support_reconciliation_receipts(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,case_id text,escalated integer not null,cleaned integer not null,failure_count integer not null,failure_details jsonb not null default '[]',created_at timestamptz not null default now());alter table public.timeline_daw_normalization_support_reconciliation_receipts enable row level security;create policy timeline_daw_normalization_support_reconciliation_owner on public.timeline_daw_normalization_support_reconciliation_receipts for select to authenticated using(owner_id=auth.uid());create policy timeline_daw_normalization_support_reconciliation_insert on public.timeline_daw_normalization_support_reconciliation_receipts for insert to authenticated with check(owner_id=auth.uid());alter table public.timeline_daw_normalization_support_worker_runs add column if not exists lease_released_at timestamptz,add column if not exists abandoned_lease boolean not null default false;create or replace function public.release_timeline_daw_normalization_support_worker(p_token text) returns boolean language plpgsql security definer set search_path=public as $$ declare released boolean;begin if current_user not in('service_role','postgres')then raise exception 'service role required';end if;update public.timeline_daw_normalization_support_worker_lease set lease_token=null,lease_expires_at=null where name='support-automation' and lease_token=p_token returning true into released;return coalesce(released,false);end $$;revoke all on function public.release_timeline_daw_normalization_support_worker(text) from public,anon,authenticated;grant execute on function public.release_timeline_daw_normalization_support_worker(text) to service_role;
